@custom-variant dark (&:is(.dark *));

@layer base {
  * {
    @apply border-border outline-ring/50;
  }

  @supports (corner-shape: squircle) {
    * {
      corner-shape: squircle;
    }
  }

  body {
    @apply bg-background text-foreground;
  }

  button:not(:disabled),
  [role="button"]:not(:disabled) {
    cursor: pointer;
  }

  html {
    @apply font-sans;
  }
}

/* Text shimmer for streaming and live-status content. */
@property --shimmer-angle {
  syntax: "<angle>";
  inherits: true;
  initial-value: 20deg;
}

@property --shimmer-image {
  syntax: "*";
  inherits: false;
}

@property --shimmer-text-fill {
  syntax: "*";
  inherits: false;
}

@theme inline {
  @keyframes tw-shimmer {
    from {
      background-position: 100% 0;
    }
    to {
      background-position: 0 0;
    }
  }
}

@utility shimmer {
  --_spread: var(--shimmer-spread, calc(3ch + 40px));
  --_base: currentColor;
  --_highlight: var(--shimmer-color, oklch(from currentColor l c h / calc(alpha * 0.2)));
  background-image: var(
    --shimmer-image,
    linear-gradient(
      calc(90deg + var(--shimmer-angle)),
      var(--_base) calc(50% - var(--_spread)),
      color-mix(in oklch, var(--_highlight), var(--_base) 50%) calc(50% - var(--_spread) * 0.5),
      var(--_highlight) 50%,
      color-mix(in oklch, var(--_highlight), var(--_base) 50%) calc(50% + var(--_spread) * 0.5),
      var(--_base) calc(50% + var(--_spread))
    )
  );
  background-repeat: no-repeat;
  background-size: calc(200% + var(--_spread) * 2) 100%;
  background-position: 0 0;
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: var(--shimmer-text-fill, transparent);
  animation: tw-shimmer var(--shimmer-duration, 2s) linear infinite;

  @variant dark {
    --_highlight: var(
      --shimmer-color,
      oklch(from currentColor max(0.8, calc(l + 0.4)) c h / calc(alpha + 0.4))
    );
  }
  &:where([dir="rtl"], [dir="rtl"] *) {
    animation-direction: reverse;
  }
}

@utility shimmer-once {
  animation-iteration-count: 1;
}
@utility shimmer-reverse {
  animation-direction: reverse;
}
@utility shimmer-none {
  --shimmer-image: none;
  --shimmer-text-fill: currentColor;
}
@utility shimmer-color-* {
  --shimmer-color: --value(--color, [color]);
  --shimmer-color: color-mix(
    in oklch,
    --value(--color, [color]) calc(--modifier(integer) * 1%),
    transparent
  );
}
@utility shimmer-duration-* {
  --shimmer-duration: calc(--value(integer) * 1ms);
}
@utility shimmer-spread-* {
  --shimmer-spread: calc(var(--spacing) * --value(integer));
  --shimmer-spread: --value([length], [percentage]);
}
@utility shimmer-angle-* {
  --shimmer-angle: calc(--value(integer) * 1deg);
}

@media (prefers-reduced-motion: reduce) {
  .shimmer {
    animation: none;
    background-image: none;
    -webkit-text-fill-color: currentColor;
  }
}

/*
 * Skeleton sweep. The gradient is attached to the viewport (`fixed`), so every
 * skeleton on screen shares one band that travels across the page at the same
 * speed regardless of element size. The Skeleton component pins each animation
 * to the document timeline so late-mounting skeletons stay in phase.
 */
@theme inline {
  --animate-skeleton: skeleton var(--shimmer-duration, 2s) -1s infinite linear;
  @keyframes skeleton {
    to {
      background-position: -200% 0;
    }
  }
}

@utility skeleton {
  background-color: var(--color-skeleton);
  background-image: linear-gradient(
    120deg,
    transparent 40%,
    var(--color-skeleton-highlight),
    transparent 60%
  );
  background-size: 200% 100%;
  background-position: 0 0;
  background-repeat: repeat;
  background-attachment: fixed;
  animation: var(--animate-skeleton);

  &:where([dir="rtl"], [dir="rtl"] *) {
    animation-direction: reverse;
  }

  @media (prefers-reduced-motion: reduce) {
    animation: none;
    background-image: none;
  }
}

