  --tag-red: #cb7676;
  --tag-orange: #d4976c;
  --tag-yellow: #e6cc77;
  --tag-yellow-foreground: #e6cc77;
  --tag-green: #4d9375;
  --tag-cyan: #5da994;
  --tag-blue: #6394bf;
  --tag-purple: #b08fdc;
  --tag-magenta: #d9739f;
  --sidebar: #121212;
